create policy companies_admin_select on public.companies for select to public using (is_admin());
create policy companies_member_select on public.companies for select to public using ((id = get_my_company()));
create policy counts_insert_member on public.counts for insert to public with check (((counted_by = auth.uid()) AND (EXISTS ( SELECT 1 FROM session_members sm WHERE ((sm.session_id = counts.session_id) AND (sm.user_id = auth.uid())))) AND (EXISTS ( SELECT 1 FROM inventory_sessions s WHERE ((s.id = counts.session_id) AND (s.status <> 'closed'::text)))) AND (pass_number >= 1) AND (pass_number <= 3)));
create policy counts_insert_supervisor on public.counts for insert to public with check (((counted_by = auth.uid()) AND (get_my_role() = 'supervisor'::text) AND is_session_participant(session_id) AND (EXISTS ( SELECT 1 FROM inventory_sessions s WHERE ((s.id = counts.session_id) AND (s.status <> 'closed'::text)))) AND (pass_number >= 1) AND (pass_number <= 3)));
create policy counts_select_own on public.counts for select to public using ((counted_by = auth.uid()));
create policy counts_select_supervisor on public.counts for select to public using (((get_my_role() = 'supervisor'::text) AND is_session_participant(session_id)));
create policy sessions_employee_select on public.inventory_sessions for select to authenticated using (((get_my_role() = 'employee'::text) AND (status <> 'closed'::text) AND (EXISTS ( SELECT 1 FROM session_members sm WHERE ((sm.session_id = inventory_sessions.id) AND (sm.user_id = auth.uid()))))));
create policy sessions_supervisor_insert on public.inventory_sessions for insert to public with check (((get_my_role() = 'supervisor'::text) AND (company_id = get_my_company()) AND is_assigned_store(store_id)));
create policy sessions_supervisor_select on public.inventory_sessions for select to public using (((get_my_role() = 'supervisor'::text) AND is_session_participant(id)));
create policy sessions_supervisor_update on public.inventory_sessions for update to authenticated using (((get_my_role() = 'supervisor'::text) AND is_session_participant(id) AND ((status <> 'closed'::text) OR (created_by = auth.uid()) OR is_company_admin(company_id)))) with check (((get_my_role() = 'supervisor'::text) AND (company_id = get_my_company()) AND ((status <> 'closed'::text) OR (created_by = auth.uid()) OR is_company_admin(company_id))));
create policy profiles_select on public.profiles for select to public using (((id = auth.uid()) OR ((get_my_role() = 'supervisor'::text) AND (company_id = get_my_company())) OR ((get_my_role() = 'supervisor'::text) AND (EXISTS ( SELECT 1 FROM (session_members sm JOIN inventory_sessions s ON ((s.id = sm.session_id))) WHERE ((sm.user_id = profiles.id) AND (s.company_id = get_my_company())))))));
create policy profiles_update on public.profiles for update to public using ((id = auth.uid()));
create policy session_members_own on public.session_members for select to public using ((user_id = auth.uid()));
create policy session_members_supervisor on public.session_members for all to public using (((get_my_role() = 'supervisor'::text) AND is_session_participant(session_id))) with check (((get_my_role() = 'supervisor'::text) AND is_session_participant(session_id)));
create policy stores_admin_write on public.stores for all to public using (is_admin()) with check (is_admin());
create policy stores_select on public.stores for select to public using (((company_id = get_my_company()) OR is_admin()));
create policy zones_member_select on public.zones for select to public using ((EXISTS ( SELECT 1 FROM session_members sm WHERE ((sm.session_id = zones.session_id) AND (sm.user_id = auth.uid())))));
create policy zones_supervisor_company on public.zones for all to public using (((get_my_role() = 'supervisor'::text) AND is_session_participant(session_id))) with check (((get_my_role() = 'supervisor'::text) AND is_session_participant(session_id)));
